/**
 * Builds and validates a topic authored by an admin (the "Manage polls"
 * workflow / website backoffice), as opposed to one generated by the batch
 * pipeline or hand-researched in chat.
 *
 * Pure and synchronous (no disk, no network, no clock) so the whole policy is
 * unit tested; manage-topics.js owns I/O, including the source-link check.
 *
 * Policy, deliberately different from vet-topic.js: an admin is the author
 * AND the reviewer, so wording heuristics (loaded language) and escalation
 * keywords are surfaced as WARNINGS, never blockers. Hard errors are only
 * things that would produce a broken or schema-invalid topic.
 */
import { LOADED_PATTERNS, resolveTier } from './vet-topic.js';
import { normalizeQuestion } from './normalize.js';
import { makeId } from './topic-id.js';
import { activeUntilFor } from './topic-lifetime.js';

const clean = v => String(v ?? '').replace(/\s+/g, ' ').trim();

function hostnameLabel(url) {
  try { return new URL(url).hostname.replace(/^www\./, '').slice(0, 40); } catch { return ''; }
}

/** Parses an https URL; returns null (not a throw) on anything unusable. */
function parseHttpsUrl(raw) {
  let u;
  try { u = new URL(raw); } catch { return null; }
  if (u.protocol !== 'https:' || !u.hostname.includes('.') || u.username || u.password) return null;
  return u.toString();
}

function len(label, s, { min, max }, errors) {
  if (s.length < min || s.length > max) errors.push(`${label}: must be ${min}–${max} characters (got ${s.length})`);
}

/**
 * @param raw  { question, yes_label, no_label, context, category, source_name,
 *               source_url, extra_source_urls, open_days, trend_score, tags,
 *               requested_by, country }  — all strings, as they arrive from a
 *               workflow input or an HTTP body
 * @param ctx  { now, rules, categoryIds, tiers, takenIds:Set, takenQuestions:Set, runId }
 *             takenIds / takenQuestions are updated on success so a bulk
 *             submission cannot contain duplicates of itself.
 * @returns { ok:true, topic, warnings } | { ok:false, errors }
 */
export function buildManualTopic(raw, ctx) {
  const { rules, now } = ctx;
  const errors = [];
  const warnings = [];

  const question = clean(raw.question);
  const yes = clean(raw.yes_label);
  const no = clean(raw.no_label);
  const context = clean(raw.context);
  const category = clean(raw.category).toLowerCase();
  const country = clean(raw.country) || 'IN';
  const requestedBy = clean(raw.requested_by);

  // ── text fields ────────────────────────────────────────────────────────────
  len('question', question, rules.question, errors);
  if (question && !question.endsWith(rules.question.mustEndWith)) {
    errors.push(`question: must end with "${rules.question.mustEndWith}"`);
  }
  len('context', context, rules.context, errors);
  len('yes_label', yes, rules.sideLabel, errors);
  len('no_label', no, rules.sideLabel, errors);
  if (yes && no && yes.toLowerCase() === no.toLowerCase()) {
    errors.push('yes_label / no_label: the two sides must be different');
  }

  if (!ctx.categoryIds.includes(category)) {
    errors.push(`category: must be one of ${ctx.categoryIds.join(', ')} (got "${category}")`);
  }
  if (!/^[A-Z]{2}$/.test(country)) errors.push(`country: must be a 2-letter code like IN (got "${country}")`);
  if (!/^[\w.@ -]{1,60}$/.test(requestedBy)) {
    errors.push('requested_by: required — who is publishing this (letters, digits, . _ @ - and spaces, up to 60)');
  }

  // ── duplicates ─────────────────────────────────────────────────────────────
  if (question && ctx.takenQuestions.has(normalizeQuestion(question))) {
    errors.push('question: an identical question already exists (validate-data rejects duplicates)');
  }

  // ── sources ────────────────────────────────────────────────────────────────
  const sources = [];
  const seen = new Set();
  const addSource = (name, rawUrl, label) => {
    const url = parseHttpsUrl(clean(rawUrl));
    if (!url) { errors.push(`${label}: must be a full https:// link (got "${clean(rawUrl).slice(0, 80)}")`); return; }
    if (seen.has(url)) return;
    seen.add(url);
    const sourceName = clean(name) || hostnameLabel(url);
    if (sourceName.length < rules.sourceName.min || sourceName.length > rules.sourceName.max) {
      errors.push(`${label}: source name must be ${rules.sourceName.min}–${rules.sourceName.max} characters (got ${sourceName.length})`);
      return;
    }
    // `verified` is derived by the link check, never authored — same rule as verify-sources.js.
    sources.push({ name: sourceName, url, verified: false });
  };

  if (!clean(raw.source_url)) errors.push('source_url: at least one source link is required');
  else addSource(raw.source_name, raw.source_url, 'source_url');
  for (const extra of clean(raw.extra_source_urls).split(/[\s,;]+/).filter(Boolean)) {
    addSource('', extra, `extra_source_urls (${extra.slice(0, 40)})`);
  }
  if (sources.length > rules.sources.max) {
    errors.push(`sources: at most ${rules.sources.max} allowed (got ${sources.length})`);
  }

  // ── numbers & tags ─────────────────────────────────────────────────────────
  const openDaysRaw = clean(raw.open_days);
  let openDays = 0;
  if (openDaysRaw !== '') {
    openDays = Number(openDaysRaw);
    if (!Number.isInteger(openDays) || openDays < rules.openDays.min || openDays > rules.openDays.max) {
      errors.push(`open_days: whole number ${rules.openDays.min}–${rules.openDays.max}, where 0 means open-ended (got "${openDaysRaw}")`);
    }
  }

  const trendRaw = clean(raw.trend_score);
  let trendScore = rules.trendScore.default;
  if (trendRaw !== '') {
    trendScore = Number(trendRaw);
    if (!Number.isInteger(trendScore) || trendScore < rules.trendScore.min || trendScore > rules.trendScore.max) {
      errors.push(`trend_score: whole number ${rules.trendScore.min}–${rules.trendScore.max} (got "${trendRaw}")`);
    }
  }

  const tags = [];
  for (const t of clean(raw.tags).toLowerCase().split(',').map(x => x.trim()).filter(Boolean)) {
    if (!/^[a-z0-9][a-z0-9 -]*$/.test(t) || t.length > rules.tags.maxLength) {
      errors.push(`tags: "${t.slice(0, 30)}" must be lowercase letters/digits/spaces/hyphens, up to ${rules.tags.maxLength} characters`);
    } else if (!tags.includes(t)) tags.push(t);
  }
  if (tags.length > rules.tags.max) errors.push(`tags: at most ${rules.tags.max} allowed (got ${tags.length})`);

  if (errors.length) return { ok: false, errors };

  // ── advisory checks (never blocking — the admin is the reviewer) ───────────
  for (const re of LOADED_PATTERNS) {
    const m = re.exec(question);
    if (m) warnings.push(`question: wording "${m[0]}" can read as leading — fine if intended`);
  }
  const { tier, escalatedBy } = resolveTier(category, question, context, ctx.tiers);
  if (escalatedBy) {
    warnings.push(`matches the escalation keyword "${escalatedBy}" — would normally need review; published directly because the admin is the reviewer`);
  }

  const nowIso = new Date(now).toISOString();
  const id = makeId(country, question, ctx.takenIds, new Date(now));
  ctx.takenQuestions.add(normalizeQuestion(question));

  const topic = {
    id,
    schemaVersion: 1,
    contentVersion: 1,
    country,
    category,
    status: 'published',
    question,
    context,
    sides: { yes, no },
    sources,
    tags,
    trendScore,
    publishedAt: nowIso,
    activeFrom: nowIso,
    activeUntil: activeUntilFor(now, openDays),
    review: {
      tier,
      state: 'approved',
      reviewedBy: requestedBy,
      reviewedAt: nowIso,
      reason: 'published directly by an admin (manage-polls)',
    },
    generation: {
      model: 'manual-console',
      pipelineRun: String(ctx.runId ?? 'local'),
      generatedAt: nowIso,
      sourceCount: sources.length,
    },
    bookmarks: 0,
  };
  return { ok: true, topic, warnings };
}
